async function writeStaffTagsPg(
  tenantId: string, userGuid: string,
  skillsRaw: string | null, tagsRaw: string | null,
): Promise<void> {
  try {
    if (skillsRaw) {
      for (const n of skillsRaw.split(",").map(s => s.trim()).filter(Boolean)) {
        const skillId = await insertSkillIfNotExists(tenantId, n);
        await insertResourceSkill({ tenantId, resourceGuid: userGuid, skillId, skillName: n, category: null, proficiency: null, yearsExperience: null, lastUsedYear: null, isPrimary: false });
      }
    }
    if (tagsRaw) {
      for (const n of tagsRaw.split(",").map(t => t.trim()).filter(Boolean)) {
        await insertExperienceTagIfNotExists(tenantId, n);
        await insertUserExperienceTag({ tenantId, resourceGuid: userGuid, tagName: n });
      }
    }
  } catch (e) {
    console.warn("[pipeline] skills/tags write failed:", String(e));
  }
}

// Per-person pay rates were removed (Option A): pay rates are ROLE-based only,
// stored on core2.dbo.Roles / RoleBillingRateByDept and written via the Roles sheet
// and the Rates screen. The Staff roster no longer imports per-person rates, so the
// old rateStr / upsertPersonRates helpers (which wrote resource_profile) are gone.

// Split a lump-sum hours total evenly across every Monday-aligned week the
// [start,end] span covers, so an imported "Total Hours" total is stored as
// real per-week rows instead of one big span+total (which makes the header %
// an averaged approximation instead of the exact weekly figure — see
// pctallocation-is-hours-not-percent memory). A single-week span returns one
// [start,end,hours] entry unchanged.
// Default lump-sum → weekly split. Every week is filled at the standard
// "hours per week" business-rule setting first (that's the expected norm for
// a full week of work); whatever hours are left over — higher OR lower than
// a clean multiple of that setting — land entirely on the LAST week of the
// span, rather than being averaged out across every week. This keeps every
// week showing the normal/expected number except the final one, which
// visibly absorbs whatever doesn't divide evenly. If the total runs out
// before every front week can be filled at the full rate (an under-funded
// span), front weeks are filled in order until hours are exhausted and any
// remaining weeks (including the last) get 0 — never negative.
// For an explicit even spread instead, see spreadEvenlyIntoWeeks() below
// (used by the "Spread evenly" button).
//
// evenFillRate: when the row's hours were DERIVED from an "Allocation %"
// (no explicit hours in the file), the user's intent is "X% of a work week,
// every week of the span" — NOT a lump total to be front-loaded at full
// 40h weeks (which made a 60% person read as 100% and then 0%). Pass the
// %-implied weekly hours here and every materialized week gets exactly that
// rate; the lump `total` is ignored in that mode.
// ── Hours-integrity guards ───────────────────────────────────────────────────
// Hours are the app's main pillar: a junk value here poisons every grid, card
// and forecast downstream. Two invariants every RA write path must hold:
//   1. A single person's week can NEVER exceed 168h (7 days × 24h).
//   2. An allocation % above MAX_SANE_ALLOC_PCT is never a real percentage —
//      the near-certain cause is total HOURS pasted into the % column (seen in
//      production: PctAllocation=400 materialized as 96h/wk phantom rows). Such
//      values are imported as hours-over-the-span instead, with a warning.
export const MAX_SANE_ALLOC_PCT = 150;
export const MAX_WEEK_HOURS = 168;
/** Physical ceiling for an RA row's hours given its date span (≥1 week's cap). */
export function physicalHoursCap(startMs: number, endMs: number): number {
  const days = Math.max(1, Math.round((endMs - startMs) / 864e5) + 1);
  return Math.max(MAX_WEEK_HOURS, days * 24);
}

function splitLumpHoursIntoWeeks(
  start: Date, end: Date, total: number, hoursPerWeek: number,
  evenFillRate?: number,
): Array<{ start: Date; end: Date; hours: number }> {
  // Snap to the Monday ON OR AFTER start so no hours bleed into schedule
  // phases that ended before the person's assignment start date.
  const mondayOnOrAfter = (d: Date): Date => {
    const x = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
    const dow = x.getUTCDay(); // 0=Sun 1=Mon … 6=Sat
    const shift = dow === 1 ? 0 : dow === 0 ? 1 : 8 - dow;
    x.setUTCDate(x.getUTCDate() + shift);
    return x;
  };
  const mons: Date[] = [];
  let cur = mondayOnOrAfter(start);
  const endT = end.getTime();
  let guard = 0;
  while (cur.getTime() <= endT && guard < 520) {
    mons.push(new Date(cur));
    cur = new Date(cur.getTime() + 7 * 864e5);
    guard++;
  }
  const n = mons.length;
  if (n <= 1) return [{ start, end, hours: total }];
  if (evenFillRate != null && evenFillRate > 0) {
    // %-derived allocation: every week of the span gets the %-implied weekly
    // hours (e.g. 60% of a 40h week = 24h EVERY week). No front-loading, no
    // last-week remainder — the "total" was synthesized from the % in the
    // first place, so the materialized weeks ARE the source of truth.
    const wk = Math.max(0, Math.round(evenFillRate));
    return mons.map((m) => {
      const weekEnd = new Date(Math.min(m.getTime() + 6 * 864e5, endT));
      return { start: m, end: weekEnd, hours: wk };
    });
  }
  const totalH = Math.round(total);
  const baseH = Math.max(0, Math.round(hoursPerWeek));
  let remaining = totalH;
  const hrs: number[] = [];
  for (let i = 0; i < n - 1; i++) {
    const wk = Math.min(baseH, remaining);
    hrs.push(wk);
    remaining -= wk;
  }
  hrs.push(remaining); // last week absorbs whatever's left (can exceed baseH)
  return mons.map((m, i) => {
    const weekEnd = new Date(Math.min(m.getTime() + 6 * 864e5, endT));
    return { start: m, end: weekEnd, hours: hrs[i] };
  });
}

// NOTE: the fair, no-bias "Spread evenly" distribution (used by the button
// in EditAllocationModal on the web) lives client-side in
// artifacts/rmone-web/src/components/EditAllocationModal.tsx — it operates on
// already-loaded phase/week data in the browser, so there's no backend
// endpoint for it. Keep that implementation's remainder distribution in sync
// with the "fair, front-loaded-by-one-hour" approach used above at import
// time if the algorithm ever changes here.

export interface PipelineRow {
  [column: string]: string | number | boolean | null;
}

export interface SheetData {
  sheetName: string;
  columns: string[];
  rows: PipelineRow[];
  /** Real worksheet row number (as seen in Excel) for each entry in `rows`.
   *  Optional — only populated by parseExcel; absent for synthesized sheets. */
  rowNums?: number[];
}

// How a run treats rows that already exist for an EXISTING client:
//   create  — first-time onboarding (no existence checks; default)
//   update  — update matching rows by natural key, insert genuinely new ones (no duplicates)
//   add     — insert only brand-new rows, leave existing rows untouched
//   replace — wipe this client's data rows first, then insert everything fresh
export type ImportMode = "create" | "update" | "add" | "replace";

// Real, server-side progress emitted as the pipeline runs so the status screen
// can show the true current step + row counts instead of a simulated bar.
export interface PipelineProgress {
  phase: string;          // human label, e.g. "Importing Client Contacts"
  table?: string;         // current core2 table being loaded
  pct: number;            // overall 0–100
  done?: number;          // rows processed so far (current table)
  total?: number;         // rows in the current table
}

// Thrown when a run must stop because its job was cancelled by the user or
// flipped failed/cancelled by another process (crash reconcile, sibling
// instance). The route layer treats it as "stop and defer to the DB status"
// rather than a normal import failure — never overwrite the external status.
export class ImportAbortedError extends Error {
  constructor(public readonly externalStatus: "failed" | "cancelled") {
    super(`Import stopped: the job was marked ${externalStatus} while the run was in progress`);
    this.name = "ImportAbortedError";
  }
}

export interface PipelineJob {
  uploadId: string;
  tenantId: string;
  sheets: SheetData[];
  adminUserId?: string;
  importMode?: ImportMode;
  // Effective missing-data defaults (built-in ← global ← per-client) resolved by
  // the route layer; falls back to the built-ins when absent.
  defaults?: OnboardingDefaults;
  // Optional progress sink — called with coarse milestones during the run. The
  // route layer wires this to the in-memory job record so /status reflects it.
  onProgress?: (p: PipelineProgress) => void;
  // Cooperative abort probe — the route layer wires this to the job's cancel /
  // external-stop flags. The pipeline consults it at phase boundaries (and the
  // route's onProgress may throw ImportAbortedError for per-batch granularity);
  // either way the run stops without finishing the remaining phases.
  shouldAbort?: () => "failed" | "cancelled" | null | undefined;
  // Username (email) of the person who initiated this upload. When set and
  // importMode is "create", the pipeline seeds this user as a site admin in the
  // new tenant so they can log in immediately.
  initiatedByUsername?: string;
  // Per-sheet forced record type set by the module-card upload UI.
  // When present for a sheet, overrides auto-detection of Project/Opportunity/Lead.
  recordTypeOverrides?: Record<string, "Project" | "Opportunity" | "Lead">;
  // Upload-time locked data category. When set, EVERY sheet is treated as this
  // type — tab names are completely ignored. Set by the module card the user
  // clicked when they uploaded (e.g. "Projects" card → "clients").
  forcedTabType?: "team" | "clients" | "assignments";
  // User-supplied disambiguation choices for divisions that exist under multiple
  // BUs. Keys are division names (lowercase). Values are either a specific
  // division ID to update (move that exact row to the new BU) or "create" to
  // insert a brand-new division under the target BU without touching existing ones.
  divisionHints?: Record<string, string>;
}

export interface PipelineResult {
  uploadId: string;
  tenantId: string;
  status: "success" | "partial" | "failed";
  // Machine-readable reason when status === "failed". Currently:
  //   "db_lock_timeout" — a SQL Server lock wait exceeded 15 s (stale session);
  //                       safe to re-upload immediately.
  // Machine-readable failure cause: "db_lock_timeout", "db_connection_lost",
  // or "strict_keys" (update-mode upload blocked by missing/unknown mandatory
  // IDs — nothing was written; errors[] carries the per-row detail).
  failureReason?: string;
  steps: StepResult[];
  // Wall-clock phase timings from runPipeline's mark() calls, persisted into the
  // job result so slow production imports can be profiled from onboarding
  // history (the console [pipeline][timing] lines are lost when the server
  // restarts). tMs = elapsed since run start, dMs = delta since previous mark.
  phaseTimings?: Array<{ label: string; tMs: number; dMs: number }>;
  // DATA rows written from the uploaded file (uploaded-sheet tables + schedule).
  // Configuration/seed writes (Config_* seeds, portal-config clone, tenant/admin
  // seed rows) are counted separately in configInserted so a 0-data-row run can
  // never masquerade as "N records inserted" (#390).
  totalInserted: number;
  // Setup/config rows the pipeline seeds on every run — reported separately.
  configInserted?: number;
  totalErrors: number;
  /** Rows HELD OUT of the import pending an admin decision (near-match person,
   *  unknown or ambiguous project reference). Not errors — they sit on the
   *  needs-attention review list until resolved, then a re-upload places them. */
  needsAttention?: number;
  errors: RowError[];
  // Values the wizard filled with a sensible DEFAULT because the client left
  // them blank. Persisted separately (our Postgres) and surfaced as an "Assumed
  // Data" flag so users can tell system-generated values from client-given ones.
  assumed?: AssumedField[];
  // Every record (entityType|naturalKey) this run processed, so saved assumed
  // flags can be auto-cleared when a re-upload supplies the real value.
  entities?: string[];
  // Human-readable warnings about non-fatal write failures (e.g. construction
  // fields that could not be persisted due to a type mismatch on a specific
  // tenant's schema). These are surfaced in the import history UI as "partial
  // write" notices so operators know to investigate without blocking the import.
  warnings?: string[];
  // Structured data for retrying failed construction field writes without
  // re-uploading the entire file. Each entry contains the table, record ID,
  // and the subset of fields that failed so the retry endpoint can call
  // supplementalRecordUpdate directly.
  constructionRetryEntries?: ConstructionRetryEntry[];
}

export type ImportRecordAttribution = {
  records: Array<{ entityType: "project" | "opportunity" | "lead" | "company" | "contact" | "staff"; entityId: string; entityName?: string | null }>;
  createdTotal: number;
  updatedTotal: number;
  truncated: boolean;
};

type ImportRecordTracker = {
  created: Map<string, { entityType: ImportRecordAttribution["records"][number]["entityType"]; entityId: string; entityName?: string | null }>;
  updated: Map<string, { entityType: ImportRecordAttribution["records"][number]["entityType"]; entityId: string; entityName?: string | null }>;
  createdTotal: number;
  updatedTotal: number;
  truncated: boolean;
  unresolved: Map<string, {
    operation: "created" | "updated";
    entityType: "company" | "contact";
    entityName: string;
    companyLookup?: string | null;
  }>;
};

const IMPORT_RECORD_AUDIT_CAP = 200;

function trackImportRecord(
  idMaps: Record<string, Map<string, any>>,
  operation: "created" | "updated",
  entityType: ImportRecordAttribution["records"][number]["entityType"],
  entityId: string | null | undefined,
  entityName?: string | null,
): void {
  const id = String(entityId ?? "").trim();
  if (!id) return;
  const holder = idMaps as any;
  const tracker: ImportRecordTracker = holder._importRecordTracker ??= {
    created: new Map(),
    updated: new Map(),
    createdTotal: 0,
    updatedTotal: 0,
    truncated: false,
    unresolved: new Map(),
  };
  const bucket = tracker[operation];
  const key = `${entityType}:${id.toLowerCase()}`;
  if (bucket.has(key)) return;
  if (operation === "created") tracker.createdTotal++;
  else tracker.updatedTotal++;
  let entityCount = 0;
  for (const value of bucket.values()) if (value.entityType === entityType) entityCount++;
  if (entityCount < IMPORT_RECORD_AUDIT_CAP) {
    bucket.set(key, { entityType, entityId: id, entityName });
  } else {
    tracker.truncated = true;
  }
}

function trackImportRecordByName(
  idMaps: Record<string, Map<string, any>>,
  operation: "created" | "updated",
  entityType: "company" | "contact",
  entityName: string,
  companyLookup?: unknown,
): void {
  const holder = idMaps as any;
  const tracker: ImportRecordTracker = holder._importRecordTracker ??= {
    created: new Map(),
    updated: new Map(),
    createdTotal: 0,
    updatedTotal: 0,
    truncated: false,
    unresolved: new Map(),
  };
  const companyKey = companyLookup == null ? "" : String(companyLookup);
  const key = `${operation}:${entityType}:${entityName.toLowerCase()}:${companyKey}`;
  if (tracker.unresolved.has(key)) return;
  if (operation === "created") tracker.createdTotal++;
  else tracker.updatedTotal++;
  let count = 0;
  for (const value of tracker.unresolved.values()) {
    if (value.operation === operation && value.entityType === entityType) count++;
  }
  if (count < IMPORT_RECORD_AUDIT_CAP) {
    tracker.unresolved.set(key, { operation, entityType, entityName, companyLookup: companyKey || null });
  } else {
    tracker.truncated = true;
  }
}

// A single system-defaulted value, linked to its record by natural key — mirrors
// the shape used for kept "extra fields" so it can be shown next to the record.
export interface AssumedField {
  entityType:  string;        // person | company | project | opportunity
  naturalKey:  string;        // stable identifier of the linked record (lowercased)
  recordLabel: string;        // human-readable label of the linked record
  fieldName:   string;        // friendly name of the defaulted field
  value:       string | null; // the assumed value that was applied
  sheetName:   string;        // source tab name (for context)
  // Data Confidence Classification (spec): how this value was derived.
  // client_provided | system_defaulted | ai_inferred | estimated | historical_derived
  confidence?: string;
}

// Collector threaded through the simplified-sheet expansion so each default we
// apply can be recorded once, keyed by record + field (last write wins).
export interface AssumedContext {
  tenantLabel: string;
  assumed: AssumedField[];
  seen: Set<string>;
  // Every (entityType|naturalKey) the expansion actually processed — used so a
  // later validated re-upload can auto-clear stale assumed flags for records it
  // covered whose fields are no longer assumed (spec: assumed → validated).
  entities: Set<string>;
  defaults: OnboardingDefaults;
  // Per-sheet forced record type from the module-card upload UI.
  // When present, overrides auto-detection of Project/Opportunity/Lead.
  recordTypeOverrides?: Record<string, "Project" | "Opportunity" | "Lead">;
  // Strict identity keys (update-mode runs): NEVER invent a login email for a
  // staff row — leave it blank so the strict-key gate blocks the upload with a
  // per-row message instead of silently minting lastname@domain.
  strictKeys?: boolean;
  // Bare-number Division/Department values dropped by expandTeamSheet (they
  // are codes, not org names — see numericOrgName guard). Collected so
  // runPipeline can surface ONE consolidated import warning listing them.
  numericOrgSkips?: Set<string>;
}

/** True when an org-name cell holds a bare number ("1732", "42.0") — that is a
 *  code/ID, never a real Division/Department/Business-Unit NAME. Client file
 *  carried "1732" in the org columns and the import minted a division AND a
 *  department literally named "1732"; every Project Coordinator then displayed
 *  "1732" on team grids. Names that merely CONTAIN digits ("Region 5",
 *  "42nd Street Office") stay legal. */
const numericOrgName = (s: string | null | undefined): boolean =>
  !!s && /^\d+(\.\d+)?$/.test(s.trim());

export interface StepResult {
  step: number;
  table: string;
  rowsAttempted: number;
  rowsInserted: number;
  rowsSkipped: number;
  /** Rows that matched an existing record and were updated in place (upsert). */
  rowsUpdated?: number;
  /** Rows skipped because the same ticket/title appeared earlier in the SAME file. */
  duplicatesInFile?: number;
  /** Rows held for admin review (needs-attention) instead of imported/errored. */
  rowsNeedsAttention?: number;
  /** True for configuration/seed steps (Config_* seeds, portal-config clone,
   *  tenant/admin seed) — setup writes, NOT data rows from the uploaded file. */
  isConfig?: boolean;
  errors: RowError[];
}

export interface RowError {
  table: string;
  rowIndex: number;
  column?: string;
  message: string;
  title?: string;
  row?: PipelineRow;
}

/** Record a finished configuration/seed step on the result: marks it isConfig
 *  and accumulates its inserted rows into result.configInserted — NEVER into
 *  totalInserted, which counts only data rows from the uploaded file (#390).
 *  Error accumulation is intentionally left to each caller (some seed steps
 *  are non-fatal and must not contribute to totalErrors). */
export function pushConfigStep(result: PipelineResult, step: StepResult): void {
  step.isConfig = true;
  result.steps.push(step);
  result.configInserted = (result.configInserted ?? 0) + step.rowsInserted;
}

/** Extract a human-readable label from a row (project name, email, etc.). */
function rowLabel(row: PipelineRow | undefined): string | undefined {
  if (!row) return undefined;
  const v = row.Title ?? (row as any)["Project Title"] ?? row.Name
         ?? (row as any).FullName ?? row.Email ?? (row as any).CompanyName;
  return v ? String(v) : undefined;
}

/** Translate a raw SQL Server / runtime error into plain English. */
function friendlyMessage(raw: string): string {
  const s = String(raw ?? "");
  if (/Error converting data type nvarchar to (bigint|int)/i.test(s))
    return "A field contains text where a number is expected. Please check that lookup/ID columns only contain numbers, or leave them blank.";
  if (/String or binary data would be truncated/i.test(s))
    return "One of the values is too long for its field — try shortening the text in this row.";
  if (/Cannot insert the value NULL into column '?(\w+)'?/i.test(s)) {
    const m = s.match(/column '?(\w+)'?/i);
    return m ? `Required field "${m[1]}" is missing — make sure this row has a value for that column.`
             : "A required field is missing from this row.";
  }
  if (/Violation of (UNIQUE KEY|PRIMARY KEY) constraint/i.test(s))
    return "This record already exists with the same key. Try using 'Update' mode to modify existing records.";
  if (/Timeout|LOCK_TIMEOUT|deadlock/i.test(s))
    return "The database timed out processing this row — this is usually temporary. Try re-importing.";
  return s;
}

// ── Access Level resolution (#155) ───────────────────────────────────────────
// Resolves an "Access Level" cell against the built-in synonyms AND the
// tenant's admin-defined custom access levels (Settings → Access Levels, the
// same doc fetchAccessLevels reads). Custom matches return the "custom:<id>"
// marker (the format staff.ts normAcl accepts); built-in isSiteAdmin/isManager
// flags stay false for custom levels. Non-empty values that match nothing come
// back in `unrecognized` so callers can surface an import warning instead of
// silently dropping the value.
export type AclResolution = { acl: string | null; unrecognized?: string };
export type AclResolver = (raw: string | null | undefined) => AclResolution;

const ACL_ADMIN_SYNONYMS = new Set([
  "admin", "administrator", "site admin", "superadmin", "super admin",
  "super-admin", "system admin", "system administrator", "full admin", "full access",
]);
const ACL_MANAGER_SYNONYMS = new Set(["manager", "mgr", "supervisor", "team lead", "team manager"]);
const ACL_USER_SYNONYMS = new Set([
  "user", "viewer", "read only", "read-only", "readonly",
  "standard", "basic", "basic user", "regular", "regular user",
]);

export function makeAclResolver(customByName: Map<string, string>, customIds: Set<string>): AclResolver {
  return (raw) => {
    const orig = String(raw ?? "").trim();
    const s = orig.toLowerCase();
    if (!s) return { acl: null };
    // Already-formatted custom marker (e.g. from a re-export): checked FIRST so
    // built-in heuristics (like the "view" substring → user) can never hijack a
    // marker whose id happens to contain a synonym (e.g. "custom:fin-view").
    // Accepted only when the level still exists; deleted levels fall through
    // as unrecognized.
    if (s.startsWith("custom:")) {
      const id = s.slice("custom:".length);
      if (customIds.has(id)) return { acl: `custom:${id}` };
      return { acl: null, unrecognized: orig };
    }
    // Custom level by exact display name wins over ALL built-in synonym checks
    // (consistent priority: a tenant-defined name always beats a heuristic).
    // Built-in admin/manager/user synonyms only apply when no custom level
    // claims the exact cell value, so a tenant can safely name a level
    // "Supervisor" or "Administrator" without it being silently mapped to the
    // built-in manager/admin tier.
    const cid = customByName.get(s);
    if (cid) return { acl: `custom:${cid}` };
    if (ACL_ADMIN_SYNONYMS.has(s)) return { acl: "admin" };
    if (ACL_MANAGER_SYNONYMS.has(s)) return { acl: "manager" };
    if (ACL_USER_SYNONYMS.has(s) || s.includes("view")) return { acl: "user" };
    return { acl: null, unrecognized: orig };
  };
}

// Built-in-only fallback used when a call site somehow runs without a
// tenant-aware resolver having been stashed on idMaps.
const BUILTIN_ACL_RESOLVER: AclResolver = makeAclResolver(new Map(), new Set());

// Build a resolver straight from a sanitized custom-levels doc. Extracted so
// the fixture check (scripts/check-access-levels.ts) exercises the exact same
// name→id/known-ids wiring the live pipeline uses.
export function makeAclResolverFromDoc(doc: { levels: Array<{ id: string; name: string }> }): AclResolver {
  const byName = new Map<string, string>();
  const ids = new Set<string>();
  for (const l of doc.levels) {
    byName.set(l.name.trim().toLowerCase(), l.id);
    ids.add(l.id);
  }
  return makeAclResolver(byName, ids);
}

async function buildAclResolver(tenantLabel: string): Promise<AclResolver> {
  try {
    const doc = await getAccessLevelsForTenant(tenantLabel);
    return makeAclResolverFromDoc(doc);
  } catch (e: any) {
    console.warn(`[pipeline] custom access-level load failed for "${tenantLabel}" (built-ins only): ${e?.message ?? e}`);
    return BUILTIN_ACL_RESOLVER;
  }
}

// Pull the tenant-aware resolver + warning collector stashed on idMaps by
// runPipeline. Warnings dedupe per distinct unrecognized value.
export function aclResolveFor(idMaps: Record<string, Map<string, any>>): {
  resolve: AclResolver;
  warnUnrecognized: (val: string, context: string) => void;
} {
  const resolve: AclResolver = (idMaps as any)._aclResolve ?? BUILTIN_ACL_RESOLVER;
  const warned: Set<string> = ((idMaps as any)._aclWarned ??= new Set<string>());
  const warnings: string[] = ((idMaps as any)._aclWarnings ??= []);
  return {
    resolve,
    warnUnrecognized: (val, context) => {
      const key = val.toLowerCase();
      if (warned.has(key)) return;
      warned.add(key);
      warnings.push(
        `Access Level "${val}" (${context}) is not a built-in level (Admin/Manager/User) or one of this company's custom access levels — it was ignored. Add it under Settings → Access Levels and re-import to apply it.`,
      );
    },
  };
}

// ── Unassigned-placeholder division helpers ───────────────────────────────────
// Extracted as pure functions so they can be unit-tested without a live DB.

/**
 * Returns true when `name` matches the tenant's unassigned-label placeholder
 * pattern (case-insensitive). `tenantLabel` defaults to "Unassigned" when blank.
 */
export function isUnassignedPlaceholderDivName(name: string, tenantLabel: string): boolean {
  const k = (name ?? "").trim().toLowerCase();
  if (!k) return false;
  const lc = ((tenantLabel ?? "").trim() || "Unassigned").toLowerCase();
  return k === "unassigned" || k === lc;
}

/**
 * Given the DB probe result for a CompanyDivisions row with the unassigned
 * placeholder name, returns the action to take before ensureManyByTitle runs.
 *
 * `found` is the first row returned by:
 *   SELECT TOP 1 ID, Deleted … ORDER BY live-first, ID
 * or null when no row exists at all.
 *
 * Actions:
 *   "use-live"   — live row already present; register id, skip INSERT.
 *   "restore"    — soft-deleted row; un-delete it, register id, skip INSERT.
 *   "create-new" — no row at all; let ensureManyByTitle create a fresh one.
 */
export function resolveUnassignedPlaceholderDivAction(
  found: { id: number; deleted: boolean } | null,
): { action: "use-live" | "restore" | "create-new"; id?: number } {
  if (!found) return { action: "create-new" };
  return found.deleted
    ? { action: "restore",  id: found.id }
    : { action: "use-live", id: found.id };
}

