// ── User groups from import ("Groups" column) ─────────────────────────────────
// Group membership lives in ONE tenant-scoped settings doc (usergroups:<tenant>,
// see routes/onboarding.ts /user-groups), NOT on user rows — so the AspNetUsers
// import passes stash {user GUID → "A; B"} pairs in idMaps._groupAssigns and
// runPipeline flushes them ONCE at the end of the run:
//   • existing groups matched by name, case-insensitively;
//   • unknown names become new groups (sanitizeUserGroups assigns palette colors);
//   • members are appended ADD-only — an import never removes group members.
// Non-fatal by design (mirrors skills/tags): a failure logs and the import
// result stands. normGroupsTenant MUST mirror normTenant in routes/onboarding.ts
// and normAcTenant in lib/access-control.ts — all three key the same rows.
import { mergeImportedGroupAssigns } from "./importGroupMerge.js";

function normGroupsTenant(t: string): string {
  return t.trim().replace(/\s+/g, "_").toLowerCase();
}

function stashImportedGroups(
  idMaps: Record<string, Map<string, any>>,
  userGuid: string,
  groupsRaw: string | null | undefined,
): void {
  if (!groupsRaw || !userGuid) return;
  const stash = (idMaps._groupAssigns ??= new Map<string, any>()) as Map<string, string>;
  const k = userGuid.toLowerCase();
  const prev = stash.get(k);
  stash.set(k, prev ? `${prev};${groupsRaw}` : groupsRaw);
}

// Returns the merge's cap-skip warnings so runPipeline can surface them in the
// import result (same surface as other import warnings) — the whole merge
// stays non-fatal; a hard failure returns its own single warning instead of
// throwing.
async function applyImportedUserGroups(
  tenantLabel: string,
  assigns: Map<string, string>,           // user GUID (lowercased) → "Group A; Group B"
): Promise<string[]> {
  if (!assigns.size) return [];
  try {
    const scope = USER_GROUPS_SCOPE_PREFIX + normGroupsTenant(tenantLabel);
    const doc = sanitizeUserGroups((await getOnboardingSettings(scope))?.settings);
    // ADD-only merge (nobody is ever removed) — pure + regression-tested in
    // lib/importGroupMerge.ts (src/lib/__tests__/importGroupMerge.test.ts).
    const { groups, added, created, warnings } = mergeImportedGroupAssigns<UserGroup>(doc.groups, assigns);
    for (const w of warnings) console.warn(`[pipeline] ${w}`);
    if (!added && !created) return warnings;
    await upsertOnboardingSettings({
      scope,
      label: tenantLabel,
      settings: sanitizeUserGroups({ groups }) as unknown as Record<string, unknown>,
    });
    // Same bust pattern as routes/onboarding.ts broadcastAccessControlBust —
    // this worker immediately, siblings via ONE IPC relay.
    bustAccessControlCache(tenantLabel);
    if (process.send) {
      try { process.send({ type: "bustCache", fn: "accessControl", tenant: tenantLabel, tid: resolveTenantId(tenantLabel) }); } catch { /* shutting down */ }
    }
    console.log(`[pipeline] user groups: +${added} membership(s), ${created} new group(s) across ${assigns.size} user(s)`);
    return warnings;
  } catch (e) {
    console.warn(`[pipeline] user-groups merge failed (non-fatal): ${e instanceof Error ? e.message : e}`);
    return [`user groups: the Groups-column merge failed (${e instanceof Error ? e.message : String(e)}) — group assignments from this file were not applied. Re-import to retry.`];
  }
}

