// Template column order (canonical keys) per tab — used to sort the mapping UI.
export const SIMPLIFIED_TEMPLATE_ORDER: Record<string, string[]> = Object.fromEntries(
  Object.entries(SIMPLIFIED_TEMPLATE_COLUMNS).map(([tab, cols]) => [tab, cols.map(c => c.key)]),
);

// Guarantee every template column is also a selectable canonical field, so the
// column-mapping dropdown always offers exactly what the downloaded template
// contains (plus any alias canonicals listed above). This prevents drift where
// a template column (e.g. ProposalPhaseDueDate) is missing from the canonical
// list, which would make it auto-detect but show a blank, unselectable dropdown.
for (const [tab, cols] of Object.entries(SIMPLIFIED_TEMPLATE_COLUMNS)) {
  const list = (SIMPLIFIED_CANONICAL_FIELDS[tab] ??= []);
  const seen = new Set(list);
  for (const c of cols) if (!seen.has(c.key)) { list.push(c.key); seen.add(c.key); }
}

// Short explanatory hints for every canonical field — shown below the field name
// in the column-mapping dropdown so users understand what each field holds.
export const SIMPLIFIED_FIELD_HINTS: Record<string, Record<string, string>> = (() => {
  const out: Record<string, Record<string, string>> = {};
  for (const [tab, cols] of Object.entries(SIMPLIFIED_TEMPLATE_COLUMNS)) {
    out[tab] = {};
    for (const c of cols) out[tab][c.key] = c.hint;
  }
  return out;
})();

/** Flat merge of all tab hints — use this when the mapped field may come from any tab. */
export const SIMPLIFIED_ALL_FIELD_HINTS: Record<string, string> = (() => {
  const out: Record<string, string> = {};
  for (const cols of Object.values(SIMPLIFIED_TEMPLATE_COLUMNS)) {
    for (const c of cols) if (!out[c.key]) out[c.key] = c.hint;
  }
  return out;
})();

// Friendly label for every canonical field (template headers + alias fallbacks
// for canonical fields the pipeline accepts but that aren't template columns).
export const SIMPLIFIED_FIELD_LABELS: Record<string, Record<string, string>> = (() => {
  const out: Record<string, Record<string, string>> = {};
  for (const [tab, cols] of Object.entries(SIMPLIFIED_TEMPLATE_COLUMNS)) {
    out[tab] = {};
    for (const c of cols) out[tab][c.key] = c.header;
  }
  const aliases: Record<string, Record<string, string>> = {
    team:    {
      AllocationStartDate: "Start Date", AllocationEndDate: "End Date",
      PctAllocation: "Allocation %", AllocationHour: "Total Hours", AllocationType: "Allocation Type",
      Office: "Office Location", Location: "Office Location",
      Created: "Created On", CreationDate: "Created On",
    },
    clients: {
      Project: "Project Title", ApproxContractValue: "Contract Value",
      AllocationStartDate: "Start Date", AllocationEndDate: "End Date",
      CloseoutStartDate: "Closeout Start Date",
    },
    assignments: {},
  };
  for (const tab of Object.keys(out)) Object.assign(out[tab], aliases[tab] ?? {});
  return out;
})();

