// ── Header normalisation for synonym lookup ──────────────────────────────────
// Collapse the cosmetic differences between how the same column gets written
// across systems so ONE alias entry covers them all:
//   "Work_Email" / "work-email" / "WorkEmail" / "WORK EMAIL" → "work email".
// Steps: split camelCase/PascalCase boundaries → lowercase → turn _ - / and
// whitespace runs into a single space → trim. "%" is preserved (used by "fte %").
export function normSynKey(s: string): string {
  return s
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .toLowerCase()
    .replace(/[_\-/]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function cleanCellText(raw: unknown): string {
  return String(raw ?? "")
    .replace(/[\u00A0\u2007\u202F]/g, " ")            // NBSP variants → space
    .replace(/[\u200B\u200C\u200D\uFEFF]/g, "")       // zero-width chars
    .replace(/^'+/, "")                                // Excel leading apostrophe
    .replace(/\s+/g, " ")
    .trim();
}
export function compactSynKey(s: string): string {
  return normSynKey(s).replace(/ /g, "");
}

// Pre-normalised synonym map — built once so every lookup is separator/case
// agnostic. On the rare normalised-key collision (e.g. "labour rate" vs
// "labor rate") the later entry wins; both already map to the same field.
const SYNONYM_MAP_NORM: Record<string, string> = (() => {
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(SYNONYM_MAP)) out[normSynKey(k)] = v;
  return out;
})();

// Per-tab canonical fields keyed by their normalised name, so a header that
// already IS a canonical field still matches regardless of case/separators
// (e.g. "status" → "Status", "company name" → "CompanyName"). Consulted AFTER
// the synonym map so deliberate synonym routing (e.g. team "email" → login)
// takes precedence. Built after the template-column backfill loop above.
const CANONICAL_NORM_BY_TAB: Record<string, Record<string, string>> = (() => {
  const out: Record<string, Record<string, string>> = {};
  for (const [tab, fields] of Object.entries(SIMPLIFIED_CANONICAL_FIELDS)) {
    const m: Record<string, string> = {};
    for (const f of fields) m[normSynKey(f)] = f;
    out[tab] = m;
  }
  return out;
})();

// Per-tab template header lookup built from SIMPLIFIED_TEMPLATE_COLUMNS.
// Consulted FIRST in the matching chain so any file using our downloaded
// template headers always maps with 100% accuracy — no synonym guessing needed.
// e.g. assignments "Team Member" → Resource, "Type" → AllocationType,
//      "Allocation %" → PctAllocation, guaranteed regardless of synonym map.
export const TEMPLATE_HEADER_NORM_BY_TAB: Record<string, Record<string, string>> = (() => {
  const out: Record<string, Record<string, string>> = {};
  for (const [tab, cols] of Object.entries(SIMPLIFIED_TEMPLATE_COLUMNS)) {
    out[tab] = {};
    for (const c of cols) out[tab][normSynKey(c.header)] = c.key;
  }
  return out;
})();

/**
 * Normalise all keys in a row using SYNONYM_MAP.
 * Canonical keys (exact match to a known field) pass through unchanged.
 * Unknown keys with no synonym → kept as-is (ignored silently downstream).
 */
function normalizeRowKeys(row: PipelineRow): PipelineRow {
  const out: PipelineRow = {};
  for (const [rawKey, val] of Object.entries(row)) {
    const canonical = SYNONYM_MAP_NORM[normSynKey(rawKey)];
    out[canonical ?? rawKey] = val;
  }
  return out;
}

// ── Simplified tab type detection ─────────────────────────────────────────────
// Column headers (normalised: lowercase, stripped of spaces/punctuation) that
// are only found in schedule / phase / timeline data and never in team, client,
// or assignment records.  A single hit is enough to classify a tab as schedule
// data and skip it — these columns simply don't exist in the other types.
const SCHEDULE_COLUMN_SIGNALS = new Set([
  // Phase / milestone vocabulary
  "phase", "phasename", "phaseno", "phasenumber", "milestone",
  // Task / activity vocabulary (MS Project, Primavera, Smartsheet…)
  "taskname", "taskid", "task", "activityname", "activityid", "activity",
  "wbs", "wbscode", "outlinelevel",
  // Duration / schedule math
  "duration", "durationdays",
  // Predecessor / dependency
  "predecessor", "predecessors", "lag", "lead",
  // Baseline columns
  "baselinestart", "baselinefinish", "baselineend",
  // Progress / completion
  "percentcomplete", "pctcomplete", "donepct", "completepct",
  // Gantt / slack
  "totalslack", "freeslack", "critical",
  // Deliverable
  "deliverable",
]);

/**
 * Returns true when a tab's columns contain schedule / phase / timeline signals
 * that clearly distinguish it from team, client, or assignment data.
 * Used instead of a hard-coded tab-name skip list so ANY client-named schedule
 * tab (e.g. "Q1 Plan", "Project Roadmap", "My Timeline") is caught correctly.
 */
export function isScheduleTabByContent(columns: string[]): boolean {
  const norm = (s: string) => s.toLowerCase().replace(/[\s\-_\/\\()%#.]+/g, "");
  const normed = columns.map(norm);
  const hit = normed.find(c => SCHEDULE_COLUMN_SIGNALS.has(c));
  if (!hit) console.log(`[pipeline] isScheduleTabByContent: no schedule signals found in [${normed.join(",")}]`);
  return !!hit;
}

// Well-known schedule tab names — used as a secondary signal when column content
// detection fails (e.g. empty sheet or headers not yet normalised).
const SCHEDULE_TAB_NAMES = new Set([
  "schedule", "phases", "phase plan", "phase schedule", "project schedule",
  "project phases", "timeline", "gantt", "work schedule", "milestone plan",
  "milestones", "construction schedule", "project timeline",
]);

/** True when either the tab name or its columns indicate a schedule/phase sheet. */
export function isScheduleTab(sheet: { sheetName: string; columns: string[] }): boolean {
  if (SCHEDULE_TAB_NAMES.has(sheet.sheetName.trim().toLowerCase())) return true;
  return isScheduleTabByContent(sheet.columns);
}

export function getSimplifiedTabType(sheetName: string): "team" | "clients" | "assignments" | null {
  const key = sheetName.trim().toLowerCase();
  if (SIMPLIFIED_TEAM_NAMES.has(key))        return "team";
  if (SIMPLIFIED_CLIENTS_NAMES.has(key))     return "clients";
  if (SIMPLIFIED_ASSIGNMENT_NAMES.has(key))  return "assignments";
  return null;
}

// ── Per-column analysis for simplified tabs ───────────────────────────────────
export type ColMatchType = "exact" | "synonym" | "llm" | "unknown";
export interface ColAnalysis {
  col:       string;
  canonical: string | null;
  matchType: ColMatchType;
}

